CREATE OR REPLACE FUNCTION public.fanmap_friend_transition(fid uuid, act text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f public.friendships; BEGIN SELECT * INTO f FROM public.friendships WHERE id=fid FOR UPDATE; IF auth.uid() IS NULL OR NOT auth.uid() IN(f.sender_id,f.receiver_id) THEN RAISE EXCEPTION 'Permission denied'; END IF; IF act='block' THEN UPDATE public.friendships SET status='blocked' WHERE id=fid; UPDATE public.location_sessions SET status='stopped',meeting_lat=NULL,meeting_lng=NULL,meeting_proposer=NULL,meeting_accepted=false WHERE least(sender_id,receiver_id)=least(f.sender_id,f.receiver_id) AND greatest(sender_id,receiver_id)=greatest(f.sender_id,f.receiver_id); DELETE FROM public.location_positions WHERE session_id IN(SELECT id FROM public.location_sessions WHERE least(sender_id,receiver_id)=least(f.sender_id,f.receiver_id) AND greatest(sender_id,receiver_id)=greatest(f.sender_id,f.receiver_id)); ELSIF act IN('accept','decline') AND f.receiver_id=auth.uid() AND f.status='pending' AND public.fanmap_verified() THEN UPDATE public.friendships SET status=CASE WHEN act='accept' THEN 'accepted' ELSE 'declined' END WHERE id=fid; ELSE RAISE EXCEPTION 'Request cannot be changed'; END IF; END $$; REVOKE ALL ON FUNCTION public.fanmap_friend_transition(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.fanmap_friend_transition(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.fanmap_location_transition(s uuid, action text, reverified boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x public.location_sessions; BEGIN SELECT * INTO x FROM public.location_sessions WHERE id=s FOR UPDATE; IF auth.uid() IS NULL OR NOT auth.uid() IN(x.sender_id,x.receiver_id) OR NOT public.fanmap_verified() OR NOT public.fanmap_friends(x.sender_id,x.receiver_id) THEN RAISE EXCEPTION 'Location permission denied'; END IF; IF action='stop' OR action='decline' THEN UPDATE public.location_sessions SET status=CASE WHEN action='stop' THEN 'stopped' ELSE 'declined' END,meeting_lat=NULL,meeting_lng=NULL,meeting_proposer=NULL,meeting_accepted=false WHERE id=s; DELETE FROM public.location_positions WHERE session_id=s; ELSIF action='accept' THEN IF auth.uid()<>x.receiver_id OR x.status<>'pending' OR x.created_at<now()-interval '5 minutes' THEN RAISE EXCEPTION 'This request cannot be accepted'; END IF; UPDATE public.location_sessions SET status='active',activated_at=now(),expires_at=now()+interval '30 minutes' WHERE id=s; ELSE RAISE EXCEPTION 'Invalid location action'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.fanmap_location_write(sid uuid, uid uuid, act text, latitude double precision DEFAULT NULL, longitude double precision DEFAULT NULL, precision_m double precision DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x public.location_sessions; f public.friendships; BEGIN SELECT * INTO f FROM public.friendships WHERE least(sender_id,receiver_id)=(SELECT least(sender_id,receiver_id) FROM public.location_sessions WHERE id=sid) AND greatest(sender_id,receiver_id)=(SELECT greatest(sender_id,receiver_id) FROM public.location_sessions WHERE id=sid) FOR UPDATE; SELECT * INTO x FROM public.location_sessions WHERE id=sid FOR UPDATE; IF f.status IS DISTINCT FROM 'accepted' OR NOT uid IN(x.sender_id,x.receiver_id) OR x.status IS DISTINCT FROM 'active' OR x.expires_at IS NULL OR x.expires_at<=now() OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=uid AND role='fan') THEN RAISE EXCEPTION 'Sharing stopped or unauthorized'; END IF; IF act='reciprocal' THEN IF uid<>x.receiver_id THEN RAISE EXCEPTION 'Not receiving friend'; END IF; UPDATE public.location_sessions SET receiver_consent=true WHERE id=sid; ELSIF act='position' THEN IF (uid=x.sender_id AND NOT x.sender_consent) OR (uid=x.receiver_id AND NOT x.receiver_consent) THEN RAISE EXCEPTION 'Consent required'; END IF; INSERT INTO public.location_positions(session_id,user_id,lat,lng,accuracy) VALUES(sid,uid,latitude,longitude,precision_m) ON CONFLICT(session_id,user_id) DO UPDATE SET lat=excluded.lat,lng=excluded.lng,accuracy=excluded.accuracy,updated_at=now(); ELSIF act='meet' THEN UPDATE public.location_sessions SET meeting_lat=latitude,meeting_lng=longitude,meeting_proposer=uid,meeting_accepted=false WHERE id=sid; ELSIF act='acceptMeeting' THEN IF x.meeting_proposer=uid OR x.meeting_lat IS NULL THEN RAISE EXCEPTION 'Other friend must accept'; END IF; UPDATE public.location_sessions SET meeting_accepted=true WHERE id=sid; ELSE RAISE EXCEPTION 'Invalid action'; END IF; END $$; REVOKE ALL ON FUNCTION public.fanmap_location_write(uuid,uuid,text,double precision,double precision,double precision) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.fanmap_location_write(uuid,uuid,text,double precision,double precision,double precision) TO service_role;
ALTER POLICY location_session_read ON public.location_sessions USING(auth.uid() IN(sender_id,receiver_id) AND public.fanmap_verified() AND public.fanmap_friends(sender_id,receiver_id) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='fan') AND (status='pending' OR (status='active' AND expires_at>now())));
CREATE OR REPLACE FUNCTION public.fanmap_location_cleanup() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN DELETE FROM public.location_positions WHERE session_id IN(SELECT id FROM public.location_sessions WHERE expires_at<=now() OR status IN('stopped','declined')); UPDATE public.location_sessions SET status='stopped',meeting_lat=NULL,meeting_lng=NULL,meeting_proposer=NULL,meeting_accepted=false WHERE expires_at<=now() AND status='active'; END $$; REVOKE ALL ON FUNCTION public.fanmap_location_cleanup() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.fanmap_location_cleanup() TO service_role;